(4341112, 624837, 82890, '<td valign="top">Very cool effect, combining the circle with the spiral... love it.</td>', 'Very cool effect, combining the circle with the spiral... love it.', '2007-12-28 13:24:53.000000', NULL, 1),
(4341113, 624432, 82890, '<td valign="top">I expected to see more shots like this, I think it''s very true to the challenge. Great!</td>', 'I expected to see more shots like this, I think it''s very true to the challenge. Great!', '2007-12-28 13:25:49.000000', NULL, 1),
(4341118, 624575, 3087, '<td valign="top">Interesting viewpoint of the city, a tiny corner, up on a fire escape balcony, having a quick smoke, whilst the rest of the city bustles by below.</td>', 'Interesting viewpoint of the city, a tiny corner, up on a fire escape balcony, having a quick smoke, whilst the rest of the city bustles by below.', '2007-12-28 13:26:37.000000', NULL, 1),
(4341119, 625436, 82890, '<td valign="top">I spent a portion of the holidays playing with my own trains... great use of depth of field.</td>', 'I spent a portion of the holidays playing with my own trains... great use of depth of field.', '2007-12-28 13:26:38.000000', NULL, 1),
(4341120, 625204, 3087, '<td valign="top">The colour toning is a little strong, in my opinion, but I like the scene, muted by the mist, very much.</td>', 'The colour toning is a little strong, in my opinion, but I like the scene, muted by the mist, very much.', '2007-12-28 13:27:12.000000', NULL, 1),
(4341121, 624777, 82890, '<td valign="top">A polarizer of may have cut out some of the haze on the distance mountain, but it''s a great shot nonetheless.</td>', 'A polarizer of may have cut out some of the haze on the distance mountain, but it''s a great shot nonetheless.', '2007-12-28 13:27:26.000000', NULL, 1),
(4341123, 624871, 3087, '<td valign="top">Interesting scene - slightly alien / sci-fi in some ways. Nice curving line of the fence, good composition with that "thing" and it''s reflection towards the right and the sun more centred. Interesting.</td>', 'Interesting scene - slightly alien / sci-fi in some ways. Nice curving line of the fence, good composition with that "thing" and it''s reflection towards the right and the sun more centred. Interesting.', '2007-12-28 13:28:04.000000', NULL, 1),
(4341125, 624977, 3087, '<td valign="top">Certainly an unusual perspective of the town!</td>', 'Certainly an unusual perspective of the town!', '2007-12-28 13:28:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4341126, 625442, 82890, '<td valign="top">Duality, reflection and contrast are used quite well. Very technically sound, but what is that guy doing? Is that his arm heading out to the right edge of the picture? I like it nonetheless!</td>', 'Duality, reflection and contrast are used quite well. Very technically sound, but what is that guy doing? Is that his arm heading out to the right edge of the picture? I like it nonetheless!', '2007-12-28 13:29:34.000000', NULL, 1),
(4341130, 625556, 82890, '<td valign="top">I''ll bet there are some great macros to be had in here as well. Love the use of reflection, though I think the darkened left side of the picture detracts (a bit) from the absolutely stunning right side.</td>', 'I''ll bet there are some great macros to be had in here as well. Love the use of reflection, though I think the darkened left side of the picture detracts (a bit) from the absolutely stunning right side.', '2007-12-28 13:30:54.000000', NULL, 1),
(4341132, 624977, 82890, '<td valign="top">Very well done... nothing to say beyond that!</td>', 'Very well done... nothing to say beyond that!', '2007-12-28 13:31:16.000000', NULL, 1),
(4341133, 624307, 3087, '<td valign="top">I''m not sure the Ile is that hidden even at this time of the morning! But this is a beautiful shot showing the serene, gentle and relaxed face of Paris!</td>', 'I''m not sure the Ile is that hidden even at this time of the morning! But this is a beautiful shot showing the serene, gentle and relaxed face of Paris!', '2007-12-28 13:31:24.000000', NULL, 1),
(4341135, 625693, 3087, '<td valign="top">Really like the way the city sweeps in a curve of light that takes up such a small part of the frame and yet is so crucial to it. Nice colours, fantastic composition, really great image!</td>', 'Really like the way the city sweeps in a curve of light that takes up such a small part of the frame and yet is so crucial to it. Nice colours, fantastic composition, really great image!', '2007-12-28 13:32:09.000000', NULL, 1),
(4341137, 625084, 3087, '<td valign="top">My preference would be for focus to be on his face rather than on the background. But very colourful, busy and exciting image.</td>', 'My preference would be for focus to be on his face rather than on the background. But very colourful, busy and exciting image.', '2007-12-28 13:32:49.000000', NULL, 1),
(4341140, 625259, 3087, '<td valign="top">Less saturated than your flickr version, assuming this is Mr Pants!<br/>Is that Marac by any chance? Nice yellow shoes, whoever''s they are! Grrrr!<br/>OR is this an entry from another DPCer who was at the same location as Mr Pants? <br/>GRIN</td>', 'Less saturated than your flickr version, assuming this is Mr Pants!Is that Marac by any chance? Nice yellow shoes, whoever''s they are! Grrrr!OR is this an entry from another DPCer who was at the same location as Mr Pants? GRIN', '2007-12-28 13:34:44.000000', NULL, 1),
(4341160, 625358, 71459, '<td valign="top">oh... freakish! What is that... well, besides a spider... I have seen other people photograph something like this, but in a different location, maybe? interesting, very Interesting!</td>', 'oh... freakish! What is that... well, besides a spider... I have seen other people photograph something like this, but in a different location, maybe? interesting, very Interesting!', '2007-12-28 13:54:28.000000', NULL, 1),
(4341312, 624546, 82890, '<td valign="top">What an odd thing... Great use of lines and perspective, though!</td>', 'What an odd thing... Great use of lines and perspective, though!', '2007-12-28 15:31:29.000000', NULL, 1),
(4341319, 624871, 82890, '<td valign="top">What an excellent shot, despite my dislike for long exposures that turn stars into lines. Fantastic!</td>', 'What an excellent shot, despite my dislike for long exposures that turn stars into lines. Fantastic!', '2007-12-28 15:33:30.000000', NULL, 1),
(4341324, 625023, 82890, '<td valign="top">The color combination here is stunning and subdued. Love it!</td>', 'The color combination here is stunning and subdued. Love it!', '2007-12-28 15:34:25.000000', NULL, 1),
(4341325, 625179, 82890, '<td valign="top">Great use of lines, though I suppose I should say that to the architects as well!</td>', 'Great use of lines, though I suppose I should say that to the architects as well!', '2007-12-28 15:35:23.000000', NULL, 1),
(4341326, 625538, 82890, '<td valign="top">Is that a scooter gang?! Great composition.</td>', 'Is that a scooter gang?! Great composition.', '2007-12-28 15:35:49.000000', NULL, 1),
(4341328, 625378, 82890, '<td valign="top">This is one of the first great uses of a lens baby I''ve seen. Very interesting!</td>', 'This is one of the first great uses of a lens baby I''ve seen. Very interesting!', '2007-12-28 15:36:45.000000', NULL, 1),
(4341335, 625298, 82890, '<td valign="top">Somehow this picture conveys community without the people. Would have been perfect for one of those challenges as well. Great shot, though it seems the perspective gets lost a little bit beyond the first porch. Did you try it a bit darker and with a bit more contrast? If you can recapture it, shrinking your depth-of-field might help too, though I''m not sure it would convey the same sense of community if the further porches were out of focus... Either way, a very simple shot, yet perfect for evoking a feeling!</td>', 'Somehow this picture conveys community without the people. Would have been perfect for one of those challenges as well. Great shot, though it seems the perspective gets lost a little bit beyond the first porch. Did you try it a bit darker and with a bit more contrast? If you can recapture it, shrinking your depth-of-field might help too, though I''m not sure it would convey the same sense of community if the further porches were out of focus... Either way, a very simple shot, yet perfect for evoking a feeling!', '2007-12-28 15:39:12.000000', NULL, 1),
(4341341, 625519, 82890, '<td valign="top">I think I would have preferred this as B&amp;W, but the composition is excellent. I feel like the red bus is detracting from Gandhi, and washing out those colors might fix that.</td>', 'I think I would have preferred this as B&W, but the composition is excellent. I feel like the red bus is detracting from Gandhi, and washing out those colors might fix that.', '2007-12-28 15:40:53.000000', NULL, 1),
(4341347, 624537, 82890, '<td valign="top">What an interesting take on Christmas! I''m curious to see if you could get the blues to show up more like greens, through some color manipulation...</td>', 'What an interesting take on Christmas! I''m curious to see if you could get the blues to show up more like greens, through some color manipulation...', '2007-12-28 15:42:10.000000', NULL, 1),
(4341349, 624440, 82890, '<td valign="top">The diffusion adds a lot to this shot, I''m a fan!</td>', 'The diffusion adds a lot to this shot, I''m a fan!', '2007-12-28 15:43:00.000000', NULL, 1),
(4341350, 625409, 82890, '<td valign="top">That''s mind-bending... and also a reminder as to why I couldn''t ever live in NYC. Good job at conveying (intentionally or unintentionally) the closeness of it all.</td>', 'That''s mind-bending... and also a reminder as to why I couldn''t ever live in NYC. Good job at conveying (intentionally or unintentionally) the closeness of it all.', '2007-12-28 15:44:13.000000', NULL, 1),
