(4347306, 625785, 88010, '<td valign="top">not quite a scrisp as I would like to see, but nice photo .</td>', 'not quite a scrisp as I would like to see, but nice photo .', '2007-12-31 09:28:37.000000', NULL, 1),
(4347506, 625217, 33672, '<td valign="top">COol shot. Nice idea. If the place is close, I''ll have to check it out....</td>', 'COol shot. Nice idea. If the place is close, I''ll have to check it out....', '2007-12-31 11:03:49.000000', NULL, 1),
(4347509, 625409, 33672, '<td valign="top">NIce wide angle shot. Interesting subject that draws you in.</td>', 'NIce wide angle shot. Interesting subject that draws you in.', '2007-12-31 11:05:25.000000', NULL, 1),
(4347512, 624955, 23433, '<td valign="top">It looks like this was not a level shot. I would vote higher if level, also it would be cool to use a little longer exposure so that the lower part of the frame had more light. I like the red glow on the mountains.</td>', 'It looks like this was not a level shot. I would vote higher if level, also it would be cool to use a little longer exposure so that the lower part of the frame had more light. I like the red glow on the mountains.', '2007-12-31 11:07:29.000000', NULL, 1),
(4347663, 625783, 83416, '<td valign="top">I like the combinations of colors and stuff in this picture  gives it a somewhat abstract feel  but unfortunately the sky looks blown.</td>', 'I like the combinations of colors and stuff in this picture  gives it a somewhat abstract feel  but unfortunately the sky looks blown.', '2007-12-31 12:18:11.000000', NULL, 1),
(4347667, 625588, 83416, '<td valign="top">Nice picture  but may require straightening and a bit more contrast.</td>', 'Nice picture  but may require straightening and a bit more contrast.', '2007-12-31 12:19:19.000000', NULL, 1),
(4347669, 625023, 83416, '<td valign="top">The light appears a bit harsh to me.</td>', 'The light appears a bit harsh to me.', '2007-12-31 12:20:02.000000', NULL, 1),
(4347672, 625440, 83416, '<td valign="top">I would like to see more detail in the upper levels.</td>', 'I would like to see more detail in the upper levels.', '2007-12-31 12:21:16.000000', NULL, 1),
(4347682, 624537, 83416, '<td valign="top">Cool shot  but afraid the voters will not like the blown out parts.</td>', 'Cool shot  but afraid the voters will not like the blown out parts.', '2007-12-31 12:24:04.000000', NULL, 1),
(4347688, 625519, 83416, '<td valign="top">Not sure what to look at in this picture. Good luck!</td>', 'Not sure what to look at in this picture. Good luck!', '2007-12-31 12:26:24.000000', NULL, 1),
(4347707, 624307, 83416, '<td valign="top">Great shot! I really like the color tone and in this case the centered composition.</td>', 'Great shot! I really like the color tone and in this case the centered composition.', '2007-12-31 12:35:53.000000', NULL, 1),
(4347709, 625204, 83416, '<td valign="top">A beautiful shot with a mood!</td>', 'A beautiful shot with a mood!', '2007-12-31 12:36:44.000000', NULL, 1),
(4347712, 625409, 83416, '<td valign="top">Great hidden perspective of the city.</td>', 'Great hidden perspective of the city.', '2007-12-31 12:38:35.000000', NULL, 1),
(4347718, 624429, 83416, '<td valign="top">The person in white may be a bit distracting  otherwise a great shot with an old feel to it.</td>', 'The person in white may be a bit distracting  otherwise a great shot with an old feel to it.', '2007-12-31 12:43:13.000000', NULL, 1),
(4347724, 625384, 83416, '<td valign="top">Not sure what was intended as a subject of this picture.</td>', 'Not sure what was intended as a subject of this picture.', '2007-12-31 12:46:36.000000', NULL, 1),
(4347727, 625770, 83416, '<td valign="top">Like the idea  but may have worked better if there actually was a city or a hint of it in the background.</td>', 'Like the idea  but may have worked better if there actually was a city or a hint of it in the background.', '2007-12-31 12:48:40.000000', NULL, 1),
(4347778, 624955, 86848, '<td valign="top">Nice shot.  I like the glow on the mountains.</td>', 'Nice shot.  I like the glow on the mountains.', '2007-12-31 13:34:06.000000', NULL, 1),
(4347786, 625178, 86848, '<td valign="top">Very nice catch.</td>', 'Very nice catch.', '2007-12-31 13:36:57.000000', NULL, 1),
(4347799, 625623, 86848, '<td valign="top">Crooked horizon is a bit distracting, but nice focus and reflections.</td>', 'Crooked horizon is a bit distracting, but nice focus and reflections.', '2007-12-31 13:47:55.000000', NULL, 1),
(4347809, 624618, 86848, '<td valign="top">Nice shot, although I think maybe a lower perspective from the tracks would look nicer.  JMHO.  :)</td>', 'Nice shot, although I think maybe a lower perspective from the tracks would look nicer.  JMHO.  :)', '2007-12-31 13:54:44.000000', NULL, 1),
(4347822, 625084, 86848, '<td valign="top">Very colorful!</td>', 'Very colorful!', '2007-12-31 14:00:13.000000', NULL, 1),
(4347908, 624710, 49109, '<td valign="top">great shadow there!</td>', 'great shadow there!', '2007-12-31 14:44:05.000000', NULL, 1),
(4347919, 625556, 30251, '<td valign="top">Super cool location.</td>', 'Super cool location.', '2007-12-31 14:50:27.000000', NULL, 1),
(4347921, 625163, 30251, '<td valign="top">This has a really cool feel to it.</td>', 'This has a really cool feel to it.', '2007-12-31 14:51:01.000000', NULL, 1),
(4347925, 625064, 30251, '<td valign="top">Great use of the wide angle and nice exposure, is this a part of your city though?</td>', 'Great use of the wide angle and nice exposure, is this a part of your city though?', '2007-12-31 14:53:11.000000', NULL, 1),
