INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4347928, 624710, 30251, '<td valign="top">Nice, good work.</td>', 'Nice, good work.', '2007-12-31 14:54:05.000000', NULL, 1),
(4347931, 625360, 30251, '<td valign="top">I''m sure you''ve gotten this, why is the image not straight to the arches? I see that that level line is straight, but visually I follow the arch line. Whatever, I love the shot. Good work.</td>', 'I''m sure you''ve gotten this, why is the image not straight to the arches? I see that that level line is straight, but visually I follow the arch line. Whatever, I love the shot. Good work.', '2007-12-31 14:57:16.000000', NULL, 1),
(4347939, 624903, 30251, '<td valign="top">Nice lighting.</td>', 'Nice lighting.', '2007-12-31 15:00:11.000000', NULL, 1),
(4347941, 625622, 30251, '<td valign="top">Great angle, I think you should go and shoot this again at sunset!</td>', 'Great angle, I think you should go and shoot this again at sunset!', '2007-12-31 15:00:50.000000', NULL, 1),
(4347942, 625127, 30251, '<td valign="top">Nice, I want to vacation there.</td>', 'Nice, I want to vacation there.', '2007-12-31 15:01:54.000000', NULL, 1),
(4347944, 624537, 30251, '<td valign="top">I like what you are doing, it''s just too processed for my taste. Is that a cactus?</td>', 'I like what you are doing, it''s just too processed for my taste. Is that a cactus?', '2007-12-31 15:03:25.000000', NULL, 1),
(4347946, 624546, 30251, '<td valign="top">Love it!! (Maybe a little more contrast to bring up the blacks)</td>', 'Love it!! (Maybe a little more contrast to bring up the blacks)', '2007-12-31 15:04:38.000000', NULL, 1),
(4347948, 624837, 30251, '<td valign="top">Great angle</td>', 'Great angle', '2007-12-31 15:04:49.000000', NULL, 1),
(4347955, 624429, 30251, '<td valign="top">This is great, has a 20''s feel to it. Nicely done.</td>', 'This is great, has a 20''s feel to it. Nicely done.', '2007-12-31 15:07:02.000000', NULL, 1),
(4347964, 625088, 30251, '<td valign="top">Did you tag that box for this challenge? Good work.</td>', 'Did you tag that box for this challenge? Good work.', '2007-12-31 15:12:05.000000', NULL, 1),
(4347967, 625339, 30251, '<td valign="top">Nice DOF</td>', 'Nice DOF', '2007-12-31 15:12:36.000000', NULL, 1),
(4347969, 625539, 30251, '<td valign="top">Great look.</td>', 'Great look.', '2007-12-31 15:13:09.000000', NULL, 1),
(4347970, 624307, 30251, '<td valign="top">Beautiful</td>', 'Beautiful', '2007-12-31 15:13:28.000000', NULL, 1),
(4347975, 625204, 30251, '<td valign="top">Great light, nice angle.</td>', 'Great light, nice angle.', '2007-12-31 15:14:36.000000', NULL, 1),
(4347977, 625409, 30251, '<td valign="top">Nice use of the wide angle.</td>', 'Nice use of the wide angle.', '2007-12-31 15:15:08.000000', NULL, 1),
(4348515, 625484, 1024, '<td valign="top">This is a fabulous find, or maybe its the processing that makes it special.  Anyway, it is wonderfully different.</td>', 'This is a fabulous find, or maybe its the processing that makes it special.  Anyway, it is wonderfully different.', '2007-12-31 19:51:59.000000', NULL, 1),
(4348517, 625409, 1024, '<td valign="top">Just the most deliciously gritty photo in this challenge!</td>', 'Just the most deliciously gritty photo in this challenge!', '2007-12-31 19:52:31.000000', NULL, 1),
(4348523, 625183, 1024, '<td valign="top">So silent, so secret.  This is almost secret gardenish.  Wonderful find.</td>', 'So silent, so secret.  This is almost secret gardenish.  Wonderful find.', '2007-12-31 19:53:40.000000', NULL, 1),
(4348528, 625178, 1024, '<td valign="top">The huge cloud above her head is totally blown out, to the point it almost seems like a cartoon dialog bubble.</td>', 'The huge cloud above her head is totally blown out, to the point it almost seems like a cartoon dialog bubble.', '2007-12-31 19:55:07.000000', NULL, 1),
(4348530, 625556, 1024, '<td valign="top">This just screams to be bigger.  I will be so glad when the size we can enter increases.  I would love to look at this again, in a bigger size.  the details are just teasing me.</td>', 'This just screams to be bigger.  I will be so glad when the size we can enter increases.  I would love to look at this again, in a bigger size.  the details are just teasing me.', '2007-12-31 19:56:26.000000', NULL, 1),
(4348536, 624710, 1024, '<td valign="top">Well someone has to do it............</td>', 'Well someone has to do it............', '2007-12-31 19:57:22.000000', NULL, 1),
(4348538, 625623, 1024, '<td valign="top">This photo has alot of wonderful potential.  Unfortunately my eye can not move past the tilted horizon.</td>', 'This photo has alot of wonderful potential.  Unfortunately my eye can not move past the tilted horizon.', '2007-12-31 19:58:36.000000', NULL, 1),
(4348579, 625360, 63398, '<td valign="top">Exquisite. Splendid find! 9</td>', 'Exquisite. Splendid find! 9', '2007-12-31 20:32:17.000000', NULL, 1),
(4348580, 625572, 63398, '<td valign="top">Terrific austere atmosphere. Hidden in plain sight....very nice.7</td>', 'Terrific austere atmosphere. Hidden in plain sight....very nice.7', '2007-12-31 20:33:22.000000', NULL, 1),
(4348582, 625178, 40355, '<td valign="top">This is a neat idea, although I''m not sure I''m a fan of the blown-out area on the sky.  The main flaw here is the lack of light on your model.  An off-camera flash - or even two pieces of posterboard as reflecters - would have thrown some light on her and brought her out of the shadows, making this a very cool shot.</td>', 'This is a neat idea, although I''m not sure I''m a fan of the blown-out area on the sky.  The main flaw here is the lack of light on your model.  An off-camera flash - or even two pieces of posterboard as reflecters - would have thrown some light on her and brought her out of the shadows, making this a very cool shot.', '2007-12-31 20:34:16.000000', NULL, 1),
(4348584, 624429, 63398, '<td valign="top">Nice grunge street look. 7</td>', 'Nice grunge street look. 7', '2007-12-31 20:34:26.000000', NULL, 1),
(4348587, 625204, 63398, '<td valign="top">Mythical, mystical, mysterious, amnd mesmerizing. Very nice image! 8</td>', 'Mythical, mystical, mysterious, amnd mesmerizing. Very nice image! 8', '2007-12-31 20:36:05.000000', NULL, 1),
(4348593, 625783, 63398, '<td valign="top">Oh, what a terrific find! I love the wild, mismatched......everything!!! Great colors, tones and textures. Definitely what they want hidden! The skull and crossbones above the pipe spewing fluid into the pond is classic!!!! 8</td>', 'Oh, what a terrific find! I love the wild, mismatched......everything!!! Great colors, tones and textures. Definitely what they want hidden! The skull and crossbones above the pipe spewing fluid into the pond is classic!!!! 8', '2007-12-31 20:40:37.000000', NULL, 1),
(4348602, 625378, 63398, '<td valign="top">A reasonably good site.....Lensbabies don''t work for me one iota; just haven''t acquired a taste for the effect, may never. Good composition, lighting, and processing, though.....</td>', 'A reasonably good site.....Lensbabies don''t work for me one iota; just haven''t acquired a taste for the effect, may never. Good composition, lighting, and processing, though.....', '2007-12-31 20:45:23.000000', NULL, 1),
(4348606, 625259, 63398, '<td valign="top">Decent graffito......don''t like the crop, and the passerby doesn''t add anything but a distraction, IMO.</td>', 'Decent graffito......don''t like the crop, and the passerby doesn''t add anything but a distraction, IMO.', '2007-12-31 20:47:43.000000', NULL, 1),
(4348612, 625611, 63398, '<td valign="top">IMO *too* buried amongst a too busy scene, and without the title, you wouldn''t know by the image that it''s Jazzbo.</td>', 'IMO *too* buried amongst a too busy scene, and without the title, you wouldn''t know by the image that it''s Jazzbo.', '2007-12-31 20:50:18.000000', NULL, 1),
(4348617, 625240, 63398, '<td valign="top">Whoa! Outstanding hidden city! What a dramatic and powerful processing technique! Very nice! 8</td>', 'Whoa! Outstanding hidden city! What a dramatic and powerful processing technique! Very nice! 8', '2007-12-31 20:56:23.000000', NULL, 1),
(4348623, 625717, 63398, '<td valign="top">I don''t really get any tie-in to a hidden city, sorry.....</td>', 'I don''t really get any tie-in to a hidden city, sorry.....', '2007-12-31 20:59:34.000000', NULL, 1),
(4348628, 624554, 63398, '<td valign="top">I don''t really see dining.....I''m guessing that''s what you meant, I see a wine cellar/room, I don''t get the woods allusion, or the hidden city tie-in. A decent, pretty image, but DNMC for me.</td>', 'I don''t really see dining.....I''m guessing that''s what you meant, I see a wine cellar/room, I don''t get the woods allusion, or the hidden city tie-in. A decent, pretty image, but DNMC for me.', '2007-12-31 21:03:08.000000', NULL, 1),
(4348631, 625183, 40355, '<td valign="top">The light in this shot is beautiful, and the symmetry between the right and left really makes it wonderful.  The tree in the center is the final touch it needed.  Very well done, subtle, and a true hidden gem in a city - 10.</td>', 'The light in this shot is beautiful, and the symmetry between the right and left really makes it wonderful.  The tree in the center is the final touch it needed.  Very well done, subtle, and a true hidden gem in a city - 10.', '2007-12-31 21:04:27.000000', NULL, 1),
(4348633, 624213, 63398, '<td valign="top">Well, OI suppose it''s hidden for sure, but it''s busy even in its narrow confines, and definitely gloomy, so I don''t get what I guess is supposed to be a tie-in with bright????</td>', 'Well, OI suppose it''s hidden for sure, but it''s busy even in its narrow confines, and definitely gloomy, so I don''t get what I guess is supposed to be a tie-in with bright????', '2007-12-31 21:04:55.000000', NULL, 1),
(4348635, 624871, 40355, '<td valign="top">A lovely night shot, the lighting is excellent and very subtle.  Great contrast between the rusty reds and the blue hues in the sky and water.  Solid 10.</td>', 'A lovely night shot, the lighting is excellent and very subtle.  Great contrast between the rusty reds and the blue hues in the sky and water.  Solid 10.', '2007-12-31 21:05:50.000000', NULL, 1),
(4348640, 624710, 40355, '<td valign="top">I hope this does well.  It''s outside-the-box, and requires some study to get, but is well worth it.  Excellent interpretation of the challenge, and very well executed.</td>', 'I hope this does well.  It''s outside-the-box, and requires some study to get, but is well worth it.  Excellent interpretation of the challenge, and very well executed.', '2007-12-31 21:07:03.000000', NULL, 1),
(4348641, 625692, 63398, '<td valign="top">I don''t really have any perspective for hidden. The image is also fairly askew as well.</td>', 'I don''t really have any perspective for hidden. The image is also fairly askew as well.', '2007-12-31 21:07:28.000000', NULL, 1),
(4348642, 625558, 40355, '<td valign="top">Lovely shot with all the muted pastel tones.  Well composed, great technicals, and beautiful scene.</td>', 'Lovely shot with all the muted pastel tones.  Well composed, great technicals, and beautiful scene.', '2007-12-31 21:08:46.000000', NULL, 1),
(4348644, 624684, 40355, '<td valign="top">Love the tones and reflections in the glass, and the slant of the composition.  A great microcosm of the city.</td>', 'Love the tones and reflections in the glass, and the slant of the composition.  A great microcosm of the city.', '2007-12-31 21:09:24.000000', NULL, 1),
(4348646, 625622, 40355, '<td valign="top">Interesting take on the challenge, but well thought-out.  Well exposed and composed, facinating to look at.  Very well done.</td>', 'Interesting take on the challenge, but well thought-out.  Well exposed and composed, facinating to look at.  Very well done.', '2007-12-31 21:10:56.000000', NULL, 1),
(4348647, 624429, 40355, '<td valign="top">The glowing steam is great, and adds wonderful dimension to this shot - the contrast between it''s softness and the hard edges of the buildings and people is great.  The B&amp;W/sepia tones are perfect.</td>', 'The glowing steam is great, and adds wonderful dimension to this shot - the contrast between it''s softness and the hard edges of the buildings and people is great.  The B&W/sepia tones are perfect.', '2007-12-31 21:12:34.000000', NULL, 1),
(4348649, 624546, 63398, '<td valign="top">How bizarre!!!! Great find! I''ll be coming back expecting an explanation! 7</td>', 'How bizarre!!!! Great find! I''ll be coming back expecting an explanation! 7', '2007-12-31 21:13:32.000000', NULL, 1),
(4348650, 624307, 40355, '<td valign="top">A great quiet scene, well fitting the title.  It shows a different side of the city, and is very well done.  Perhaps a bit tighter of a zoom on an area would have made it more intense, but still very well done. 9</td>', 'A great quiet scene, well fitting the title.  It shows a different side of the city, and is very well done.  Perhaps a bit tighter of a zoom on an area would have made it more intense, but still very well done. 9', '2007-12-31 21:13:42.000000', NULL, 1),
(4348651, 624575, 40355, '<td valign="top">The "ghost" adds a final element, but the scene itself is perfect - a great representation of this facet of city life.  Excellent technicals and visually facinating to study.  9</td>', 'The "ghost" adds a final element, but the scene itself is perfect - a great representation of this facet of city life.  Excellent technicals and visually facinating to study.  9', '2007-12-31 21:15:12.000000', NULL, 1),
(4348661, 625308, 63398, '<td valign="top">I''m just trying to be constructive, which is difficult because this misses the mark for me so completely. Hidden Swamp???? I don''t see any tie-in to this challenge.....and I have to take your word for that as I don''t even have a glimpse of what may be hidden. On my monitor, the PP in the sky looks pretty overdone, and the tonal ranges leave the image dull and flat. Please PM me if you''d like to discuss this comment</td>', 'I''m just trying to be constructive, which is difficult because this misses the mark for me so completely. Hidden Swamp???? I don''t see any tie-in to this challenge.....and I have to take your word for that as I don''t even have a glimpse of what may be hidden. On my monitor, the PP in the sky looks pretty overdone, and the tonal ranges leave the image dull and flat. Please PM me if you''d like to discuss this comment', '2007-12-31 21:20:31.000000', NULL, 1),
(4348665, 624871, 63398, '<td valign="top">Excellent hidden scene! 8</td>', 'Excellent hidden scene! 8', '2007-12-31 21:21:39.000000', NULL, 1),
(4348667, 625623, 77196, '<td valign="top">Needs straightening, unless the sliding downhill to the left was intentional. Otherwise, a decent night shot. Building on left is a bit dark, and the white building just jumps out and almost overpowers the scene.</td>', 'Needs straightening, unless the sliding downhill to the left was intentional. Otherwise, a decent night shot. Building on left is a bit dark, and the white building just jumps out and almost overpowers the scene.', '2007-12-31 21:22:36.000000', NULL, 1),
(4348678, 625623, 63398, '<td valign="top">Nice image......a little trouble with the horizon?</td>', 'Nice image......a little trouble with the horizon?', '2007-12-31 21:32:51.000000', NULL, 1),
(4348685, 625183, 63398, '<td valign="top">Great setting, composition, lighting.....just a terrific image! 7</td>', 'Great setting, composition, lighting.....just a terrific image! 7', '2007-12-31 21:38:27.000000', NULL, 1),
(4348687, 625751, 63398, '<td valign="top">Spectacular image! Where''s the city?</td>', 'Spectacular image! Where''s the city?', '2007-12-31 21:39:00.000000', NULL, 1),
(4348688, 625384, 63398, '<td valign="top">I''m not getting a grasp of hidden....sorry.</td>', 'I''m not getting a grasp of hidden....sorry.', '2007-12-31 21:40:52.000000', NULL, 1),
(4348692, 625785, 63398, '<td valign="top">Great image, but I have to take your word for the city part.....the image does not convey that.</td>', 'Great image, but I have to take your word for the city part.....the image does not convey that.', '2007-12-31 21:42:35.000000', NULL, 1),
(4348694, 625231, 63398, '<td valign="top">I don''t get this at all.</td>', 'I don''t get this at all.', '2007-12-31 21:44:00.000000', NULL, 1),
(4348696, 625339, 63398, '<td valign="top">Hidden??????</td>', 'Hidden??????', '2007-12-31 21:45:56.000000', NULL, 1),
(4348706, 624432, 63398, '<td valign="top">Way Cool! Good find....nice setup with it "tucked away" while the world whizzes past. If this doesn''t hit the Top 10, I''m nominating it for a Posthumous Ribbon! 8</td>', 'Way Cool! Good find....nice setup with it "tucked away" while the world whizzes past. If this doesn''t hit the Top 10, I''m nominating it for a Posthumous Ribbon! 8', '2007-12-31 21:52:50.000000', NULL, 1),
(4348707, 624618, 63398, '<td valign="top">Tracks aren''t rusty and I don''t see the tie-in with a city.</td>', 'Tracks aren''t rusty and I don''t see the tie-in with a city.', '2007-12-31 21:53:47.000000', NULL, 1),
(4348710, 625298, 63398, '<td valign="top">Great glimpse......almost didn''t look at this one enough. Very subtle and encompassing image after a good look. 7</td>', 'Great glimpse......almost didn''t look at this one enough. Very subtle and encompassing image after a good look. 7', '2007-12-31 21:55:50.000000', NULL, 1),
(4348712, 624603, 63398, '<td valign="top">Pretty terrific, IMO the ledge/floor at the front should have been cropped. 7</td>', 'Pretty terrific, IMO the ledge/floor at the front should have been cropped. 7', '2007-12-31 21:58:22.000000', NULL, 1),
(4348714, 625594, 63398, '<td valign="top">Dark, dismal, and depressing......well done. 8</td>', 'Dark, dismal, and depressing......well done. 8', '2007-12-31 22:00:16.000000', NULL, 1),
(4348805, 625308, 80859, '<td valign="top">it doesn''t look like conditions were ideal for photo-taking that day.  a more saturated blue sky would have helped.</td>', 'it doesn''t look like conditions were ideal for photo-taking that day.  a more saturated blue sky would have helped.', '2007-12-31 23:53:59.000000', NULL, 1),
(4348810, 625187, 80859, '<td valign="top">photo is either too dark (trees) or too white (sky) and i want to see the hidden city.  maybe doing it in b&amp;w might have worked.</td>', 'photo is either too dark (trees) or too white (sky) and i want to see the hidden city.  maybe doing it in b&w might have worked.', '2007-12-31 23:57:52.000000', NULL, 1),
(4348815, 625019, 80859, '<td valign="top">it''s a neat statue, but i don''t understand how it meets the challenge.  the flag pole is a bit distracting.  maybe from another angle without the flagpole or where the statue does not obstruct parts of the pole/flag.  i like the sky and the colours of the clouds.</td>', 'it''s a neat statue, but i don''t understand how it meets the challenge.  the flag pole is a bit distracting.  maybe from another angle without the flagpole or where the statue does not obstruct parts of the pole/flag.  i like the sky and the colours of the clouds.', '2008-01-01 00:01:36.000000', NULL, 1),
