(4353052, 624903, 88307, '<td valign="top">Clever and interesting</td>', 'Clever and interesting', '2008-01-02 07:40:57.000000', NULL, 0),
(4353079, 625543, 23484, '<td valign="top">I really like this shot Raish. I gave it an 8.</td>', 'I really like this shot Raish. I gave it an 8.', '2008-01-02 08:07:38.000000', NULL, 0),
(4353080, 625360, 5354, '<td valign="top">Well I''d never have guessed this was yours. Great top ten effort.</td>', 'Well I''d never have guessed this was yours. Great top ten effort.', '2008-01-02 08:08:22.000000', NULL, 0),
