(4353439, 624546, 48245, '<td valign="top">cool. I looked this up on the internet... have to stop by there some time.</td>', 'cool. I looked this up on the internet... have to stop by there some time.', '2008-01-02 10:09:32.000000', NULL, 0),
(4353443, 625298, 59276, '<td valign="top">I love this one......I like how the ivy is framing the first porch. Great eye! I gave you a 10.....realy thought it would do better.<br/><br/><i>Message edited by author 2008-01-02 11:02:53.</i></td>', 'I love this one......I like how the ivy is framing the first porch. Great eye! I gave you a 10.....realy thought it would do better.', '2008-01-02 10:10:32.000000', '2008-01-02 11:02:53.000000', 0),
(4353536, 625204, 24454, '<td valign="top">Yayy!  I thought I might be seeing this one again with top honors :)   Congratulations!  This is very ribbonworthy!<br/> <br/></td>', 'Yayy!  I thought I might be seeing this one again with top honors :)   Congratulations!  This is very ribbonworthy! ', '2008-01-02 10:41:30.000000', NULL, 0),
