(4353584, 624710, 30861, '<td valign="top">Sheesh, I''m embarrassed; count me as one of those who utterly missed the "city" part of this one :-( We ought to petition SC for a retroactive voting adjustment on this shot LOL.</td>', 'Sheesh, I''m embarrassed; count me as one of those who utterly missed the "city" part of this one :-( We ought to petition SC for a retroactive voting adjustment on this shot LOL.', '2008-01-02 11:02:52.000000', NULL, 0),
(4353704, 625543, 66384, '<td valign="top">This is beautiful, Peter. It doesn''t say "Christmas" to me, but I love the colors and mood of the shot. My first impression was of oriental art, with that color cast, the black ink-like tree branches, the vertical feel of the hill, and the foggy/smoky Nirvana effect. Once again I love your processing.</td>', 'This is beautiful, Peter. It doesn''t say "Christmas" to me, but I love the colors and mood of the shot. My first impression was of oriental art, with that color cast, the black ink-like tree branches, the vertical feel of the hill, and the foggy/smoky Nirvana effect. Once again I love your processing.', '2008-01-02 11:35:34.000000', NULL, 0),
(4353716, 625594, 42013, '<td valign="top">Congrats! very well deserved.</td>', 'Congrats! very well deserved.', '2008-01-02 11:40:40.000000', NULL, 0),
(4353717, 624352, 66384, '<td valign="top">Great idea for this challenge, the air shaft/inner court yard. As usual, I really like your composition. And I love the light in this.</td>', 'Great idea for this challenge, the air shaft/inner court yard. As usual, I really like your composition. And I love the light in this.', '2008-01-02 11:41:10.000000', NULL, 0),
(4353725, 625770, 66384, '<td valign="top">This is a beautiful picture. I love the light and color. I''m sure you realize this would have done a lot better in another challenge.</td>', 'This is a beautiful picture. I love the light and color. I''m sure you realize this would have done a lot better in another challenge.', '2008-01-02 11:45:28.000000', NULL, 0),
(4353882, 625217, 30861, '<td valign="top">You was robbed! This was my top pick of the challenge. Congrats on top 20 anyway, friend!</td>', 'You was robbed! This was my top pick of the challenge. Congrats on top 20 anyway, friend!', '2008-01-02 12:34:32.000000', NULL, 0),
(4353964, 625543, 62318, '<td valign="top">Yikes, scary scene. I think the processing lends alot to the mood of this image. My only suggestion might be to do a slight crop of the bottom for the fencing down there, but it is such a minor thing. Well done.</td>', 'Yikes, scary scene. I think the processing lends alot to the mood of this image. My only suggestion might be to do a slight crop of the bottom for the fencing down there, but it is such a minor thing. Well done.', '2008-01-02 12:52:21.000000', NULL, 0),
(4353981, 625594, 52549, '<td valign="top">Congrats on the blue ribbon. Excellent image.</td>', 'Congrats on the blue ribbon. Excellent image.', '2008-01-02 13:02:03.000000', NULL, 0),
